#!/bin/sh
#flux: --output=${logfile}
#flux: --error=${logfile}
#flux: --nodes=1
#flux: --ntasks=1
#flux: --cpus-per-task=1
#flux: --mem=4G
#flux: --job-name=j${job_name}
#flux: --account=AQM-DEV
#flux: --time=${task_cpu}
# The PBS 'place=shared' directive does not have a direct equivalent in Flux.
# Node sharing is typically the default behavior in Flux partitions/queues,
# so the performance should be comparable.
# The PBS '-q dev_transfer' directive does not have a direct batch directive
# equivalent in Flux. The queue/partition must be specified at submission time,
# for example: flux submit -q dev_transfer <script_name>
# 
# 
#### 
##
##  Provide fix date daily Hysplit data processing
##
   module load prod_util

   FIRSTDAY=${FIRSTDAY}
   LASTDAY=${LASTDAY}
   exp=${exp}
   remote_user=${remote_user}
   remote_host=${remote_host}
   remote_dir=${remote_dir}
   file_hd=${file_hd}
   file_type=${file_type}
   flag_update=${flag_update}
   fig_dir=${fig_dir}
   declare -a cyc=( ${cyc_opt[@]} )

   NOW=${FIRSTDAY}
   while [ ${NOW} -le ${LASTDAY} ]; do
      YY=`echo ${NOW} | cut -c1-4`
      YM=`echo ${NOW} | cut -c1-6`

      for i in "${cyc[@]}"; do
         cycle=t${i}z
         data_dir=${fig_dir}.${NOW}${i}
         if [ -d ${data_dir} ]; then
            scp ${data_dir}/${file_hd}*${file_type} ${remote_user}@${remote_host}:${remote_dir}/${YY}/${NOW}/${cycle}
         else
            echo "Can not find ${data_dir}, skip to next cycle/day"
         fi
      done  ## cycle time
      cdate=${NOW}"00"
      NOW=$(${NDATE} +24 ${cdate}| cut -c1-8)
   done
   if [ "${flag_update}" == "yes" ]; then
      script_dir=/lfs/h2/emc/physics/noscrub/${USER}/WEB/base
      cd ${script_dir}

      script_name=wcoss.run.cmaq_o3.sh
      bash ${script_name} ${LASTDAY}

      script_name=wcoss.run.cmaq2_o3.sh
      bash ${script_name} ${LASTDAY}
   fi
exit

